class Solution:
    def deliveryRange(self, times: List[int], target: int) -> List[int]:
        lo, hi = 0, len(times) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if times[mid] == target:
                a = b = mid
                while a > 0 and times[a - 1] == target:
                    a -= 1
                while b < len(times) - 1 and times[b + 1] == target:
                    b += 1
                return [a, b]
            if times[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return [-1, -1]

