class Solution:
    def deliveryRange(self, times: List[int], target: int) -> List[int]:
        def first_at_least(x):
            lo, hi = 0, len(times)
            while lo < hi:
                mid = (lo + hi) // 2
                if times[mid] < x:
                    lo = mid + 1
                else:
                    hi = mid
            return lo
        a = first_at_least(target)
        if a == len(times) or times[a] != target:
            return [-1, -1]
        return [a, first_at_least(target + 1) - 1]

code.java:
class Solution {
    public int[] deliveryRange(int[] times, int target) {
        int a = firstAtLeast(times, target);
        if (a == times.length || times[a] != target) return new int[] {-1, -1};
        return new int[] {a, firstAtLeast(times, target + 1) - 1};
    }

    private int firstAtLeast(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] < x) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

