public:
    vector<int> deliveryRange(vector<int>& times, int target) {
        int a = lower_bound(times.begin(), times.end(), target) - times.begin();
        if (a == (int) times.size() || times[a] != target) return {-1, -1};
        int b = lower_bound(times.begin(), times.end(), target + 1) - times.begin();
        return {a, b - 1};
    }
};

