static int firstAtLeast(const int* a, int n, int x) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1; else hi = mid;
    }
    return lo;
}

int* deliveryRange(int* times, int timesSize, int target, int* returnSize) {
    int* out = malloc(2 * sizeof(int));
    *returnSize = 2;
    int a = firstAtLeast(times, timesSize, target);
    if (a == timesSize || times[a] != target) {
        out[0] = out[1] = -1;
        return out;
    }
    out[0] = a;
    out[1] = firstAtLeast(times, timesSize, target + 1) - 1;
    return out;
}
